`timescale 1ns / 1ps
// blink - a binary counter on the LEDs: led[0] blinks at 1 Hz, led[1] at 0.5 Hz, and so on.
//
// Generated by `forge.py new --template blink` for a {{CLK_HZ}} Hz board clock.
// It is a starting point: replace it with your own design and keep forge.toml's `top` in sync.
module blink #(
    parameter integer CLK_HZ         = {{CLK_HZ}},
    parameter integer N_LED          = {{N_LED}},
    parameter         LED_ACTIVE_LOW = {{LED_ACTIVE_LOW}}
) (
    input  wire             clk,
    output wire [N_LED-1:0] led
);
    // Count half a second of clock cycles, then step the LED counter.
    localparam integer HALF_SEC = CLK_HZ / 2;

    reg [$clog2(HALF_SEC)-1:0] div   = 0;
    reg [N_LED-1:0]            count = 0;

    always @(posedge clk) begin
        if (div == HALF_SEC - 1) begin
            div   <= 0;
            count <= count + 1'b1;
        end else begin
            div <= div + 1'b1;
        end
    end

    assign led = LED_ACTIVE_LOW ? ~count : count;
endmodule
